using A = BoatsNBeasts.Core.LandingAction;
using D = BoatsNBeasts.Core.SeaDuty;
using J = BoatsNBeasts.Core.SeaJob;
using S = BoatsNBeasts.Core.YardSite;

namespace BoatsNBeasts.Core;

public static partial class FarLedger
{
    static CampaignArc Bottlebrush() => CampaignArc.Create("Bottlebrush Reach","The Glass Nursery",
        "The green bottles of the Reach grow in wicker frames. Their mouths catch morning air for divers. This spring the divers surface with tiny towns clinging to their sleeves. Beneath the orchard a reef calf is trying to nurse on the glass roots.",
        "A nursery bottle cut so a calf can breathe through either end",
        new("Cella Wick  /  glass diver",
            "Who will make the first opening?",
            "A school swims outside the orchard wall. Cella can ask the growers to dismantle a year’s green bottles, or guide the animals through the dangerous channel her sister surveyed. Cella will dive either way.",
            "Lift the growers’ frames",
            "Follow the sister’s cut",
            "The growers haul the rattling frames away by lamplight. Nobody counts the broken crop.",
            "Cella sews her sister’s yellow survey ribbon to the tow boat. The divers take the first two bends in silence."),
        10,
        [
            Crossing("wake-green-glass",D.Sounding,"A Mouthful of Houses",
                "Cella has a miniature chimney stuck in the cuff of her suit. The reef kids have been rubbing their new settlements loose against a submerged orchard wall.","Take soundings along the rubbed wall and find the youngest calf.",
                "Corkbill Grebe","The baby has six chimney pots on its nose. Pip says it looks like the hat of a rather important mayor.",8,J.Track,J.Sound,J.Relay),
            Landfall("wake-root-rules","A Window for a Mouth",
                "The old master diver fitted one-way valves to the bottles so his hands could come up anywhere for air. A calf is too big to get a second breath.","Stopcock Seal","Cella hears the calf blow bubbles through the new gap. The bubbles smell of somebody’s onion soup.",8,
                At(A.Brace,S.West,"Root basket","Brace the bottle roots above the calf"),
                At(A.Turn,S.East,"Breathing valve","Turn the old valve into the current"),
                At(A.Cut,S.Ferry,"Glass lip","Open the mouth of the nursery bottle")),
            Crossing("wake-lift-glass",D.Convoy,"Nobody Counts the Crop",
                "The orchard crews have tied their suspended rows into loose booms. Cella takes the smallest tow; her hands are the only ones that can feel a calf knocking on the other side.","Tow the glass booms apart and shepherd the young through.",
                "Rackjaw","The orchard loses twelve bottles. One mother carefully leaves twelve pearls on the floating scale.",8,J.Tow,J.Cut,J.Guide),
            Landfall("wake-white-flaw","The Flaw in the White Glass",
                "Cella has kept a rejected bottle under her bunk for nineteen years. A flaw in the glass traces her sister’s last route downward. On the calf’s back she finds the same trail carved in fresh chalk.","Vitreous Dormouse","The mark belongs to a young diver who learned the route by following the calves. Cella’s sister had been teaching them where to surface.",8,
                At(A.Seat,S.West,"White bottle","Set the bottle against the calf’s survey chalk"),
                At(A.Haul,S.Crane,"Diving basket","Lift the basket through the old survey shaft"),
                At(A.Guide,S.Stairs,"Young surveyor","Bring the returning diver out of the chimney bed")),
            Crossing("wake-nursery-count",D.Salvage,"Five Pairs and a Green Bottle",
                "Five adult wakes lead out of the orchard. A small sixth wake circles a green bottle anchored to the floor by a drowned lift. Cella has been asked for an exact count.","Raise the lift and return the small calf’s bottle to its traveling school.",
                "Ballast Mink","A sixth mother has been swimming upside down beneath the baby. Cella dips the count sheet under the surface for her signature.",8,J.Track,J.Salvage,J.Unload),
            Crossing("wake-bottle-school",D.Convoy,"Windows That Travel",
                "The builders want to put the nursery back where it stood. Cella suggests fitting runners to its oldest root frames. The calves can push them wherever they wish to nurse.","Bring the traveling bottle nursery out to the free water.",
                "The Bottle Train","By morning an orchard frame stands outside Last Light. A calf puts its nose through the new window, waits for breakfast, and looks offended by the portion.",8,J.Tow,J.Guide,J.Relieve,J.Relay)
        ],
        Crossing("wake-yellow-cut",D.Hunt,"Her Sister’s Cut",
                "A yellow ribbon trails from a sea swallow that nested in the old survey helmet. Cella knows her sister weighted the last turn differently from the published chart.","Follow the swallow and drive the canal watcher away from the narrow turn.",
                "Ribbonsnout","The last turn is wide enough for exactly one mother and child side by side. Cella does not need the chart again.",8,J.Track,J.Bait,J.DriveOff));

    static IslandStory[] BottlebrushIsles() => [
        Isle("Bottlebrush Reach",10,"Tumbler Bank","Rim Bel, apprentice annealer",
            "A furnace raft cooled on one side. Every single tumbler rolls uphill. Rim wants to save the shop before her father sees its breakfast glasses walk away.",
            "A glass that rolls back to its maker",
            new PostLetter("A nest of three uphill tumblers",
                "Can your little glasses bring a letter back against the current? A nursery diver wants to write home.",
                "We tried it at dinner. The smallest glass made the round trip with a reply inside and a fingerprint in the jam."),
            Crossing("wake-roll-trail",D.Hunt,"Breakfast Goes Uphill",
                "Rim has set the best glass on the dock. It rolls out to sea without sinking.","Follow the tumblers to the tilted cooling bank.",
                "Cupwing Coot","The glasses are climbing a warm upwelling. A reef calf underneath has caught its ear on the furnace anchor.",8,J.Track,J.Bait,J.DriveOff),
            Landfall("wake-roll-brick","Firebrick for a Pillow",
                "The furnace must stay level while the calf uncurls its ear. Rim’s father knows the brick pattern by the sound each one makes under his shoe.","Kiln Tick","The calf floats away with a warm patch where its ear has been. Her father suggests a new line of hot-water bottles.",8,
                At(A.Brace,S.West,"Furnace corner","Brace the high corner before shifting the firebox"),
                At(A.Haul,S.Crane,"Crooked anchor","Lift the anchor off the calf’s ear"),
                At(A.Seat,S.East,"Loose firebrick","Seat the firebrick in the low corner")),
            Crossing("wake-roll-post",D.Convoy,"The Return Address",
                "Now the glasses behave normally, Rim needs one that can travel upstream to carry the diver’s post. Her father puts the rejected stock on a little tow.","Carry the special tumblers to the return current.",
                "Spiral Perch","The first reply arrives before the last glass has left. It says the sender forgot her spectacles.",8,J.Tow,J.Sound,J.Guide),
            Landfall("wake-roll-shelf","A Shelf With Two Ends",
                "Rim builds a sorting shelf for cups that move both ways. Somebody has written the address underneath the cups.","Parcel Newt","Rim places a mirror under the shelf. She can sort the mail without reading anyone’s letter.",8,
                At(A.Turn,S.West,"Sorting rollers","Reverse the rollers on the return side"),
                At(A.Seat,S.East,"Silvered shelf","Fit the mirror under the cups"),
                At(A.Guide,S.Stairs,"First correspondent","Guide the diver to the first rolling reply"))),
        Isle("Bottlebrush Reach",10,"Helmet Moss","Urs Redcap, helmet gardener",
            "Divers leave their helmets here to grow a lining of soft moss. A colony has stopped returning its helmets. They keep turning up on a little row of underwater scarecrows.",
            "A red tuft that stays dry on a wet pillow",
            new PostLetter("A patch of nursery moss in a copper cap",
                "Dear Urs, can the moss tell when an empty helmet ought to be given back?",
                "It let go the day the scarecrow lost its chick. Please send us two empty hats next spring."),
            Landfall("wake-moss-queue","The Waiting Heads",
                "Urs counts seven borrowed helmets and six scarecrows. The smallest moss patch is still humming.","Lining Louse","Inside the moss is a baby chimney swift. The scarecrows are diving bells for birds.",8,
                At(A.Turn,S.East,"Helmet visor","Open the empty helmet to the light"),
                At(A.Haul,S.Crane,"Moss sling","Lower soft moss beside the chick"),
                At(A.Brace,S.West,"Scarecrow shoulder","Brace the post under the occupied helmet")),
            Crossing("wake-moss-visors",D.Salvage,"Seven Windows",
                "A squall sank a crate of clear visors between the roost and the orchard. The birds need light to find their own helmets after dusk.","Raise the replacement visors without dragging the nests.",
                "Visor Skate","Urs holds the glass to the sky. Seven small shadows pass across it in a row.",8,J.Sound,J.Salvage,J.Unload),
            Landfall("wake-moss-doors","Windows for Birds",
                "The divers want their expensive helmets back. Urs has learned the birds follow the moss rather than the brass.","Rivet Cricket","All seven nests take to their lighter windows. The smallest chick disapproves of the new furniture and tells everyone.",8,
                At(A.Seat,S.East,"Clear nesting visor","Seat the new window above the nesting moss"),
                At(A.Cut,S.West,"Old liner thread","Free the moss from the brass shell"),
                At(A.Guide,S.Ferry,"Rookery gardener","Escort Urs to count the occupied windows")),
            Crossing("wake-moss-hats",D.Convoy,"The Hats Come Home",
                "Seven unoccupied helmets make a bad sound in a heavy swell. Urs has padded each with an old woolly hat. One of the hats is labeled Captain.","Bring the divers’ helmets back across the glass shoals.",
                "Brass Oyster","Vara wears the Captain hat for one watch. It slips over both ears and the crew has the quietest crossing on record.",8,J.Tow,J.Relieve,J.Guide)),
        Isle("Bottlebrush Reach",10,"Siphon Stairs","Essa Vale, municipal drink tester",
            "The public drinking taps are drawing everybody’s soup from yesterday. Essa has identified five respectable households and one extremely peppery submarine.",
            "An enamel cup with a pepper seed under its rim",
            new PostLetter("A sealed cup of peppery tap water",
                "Would the cook who sent pepper through the taps mind signing our water report?",
                "Gladly. I also sent cloves on Thursday. You may want to look at the pipes under the bakery."),
            Crossing("wake-soup-source",D.Sounding,"Five Households and Pepper",
                "The stranger with the pepper submarine has been accused of letting her bilge into the drinking water. Essa insists on tasting her way upstream before anyone pays a fine.","Trace the returning currents to the uphill tank.",
                "Pepper Tern","Fresh bubbles put a ring of cloves around a broken municipal pipe. The submarine has merely been cooking.",8,J.Track,J.Sound,J.Relay),
            Landfall("wake-soup-valve","Yesterday’s Tap",
                "A calf has leaned on a return valve for the comforting vibration. It moves away whenever anyone brings a wrench near.","Faucet Otter","The calf settles beside a new vibrating handrail. The submarine cook dips her ladle in the public water and declares it regrettably bland.",8,
                At(A.Brace,S.West,"Humming handrail","Brace a sounding handrail beside the calf"),
                At(A.Turn,S.East,"Return valve","Reverse the valve beneath the old steps"),
                At(A.Guide,S.Ferry,"Water tester","Escort Essa down to sample the first clean cup")),
            Crossing("wake-soup-ladle",D.Salvage,"The Clove Witness",
                "The cook says her great-grandmother planted the first drinking stand. Her ladle went down with the stand during the great storm.","Raise the original ladle from the public cistern.",
                "Cloveback","There are three names beaten into the handle. One belongs to a cook, one to a plumber and one to the calf that carried them here.",8,J.Track,J.Salvage,J.Unload),
            Landfall("wake-soup-sign","A Public Cup",
                "The three names need a public place at the stairs. The old sign has room for only one.","Signet Whelk","Essa hangs the ladle from a long string. Everyone who takes a drink holds all three names in their hand.",8,
                At(A.Cut,S.West,"Old sign straps","Cut the solitary name plate free"),
                At(A.Seat,S.East,"Ladle bracket","Set the ladle bracket above the clean tap"),
                At(A.Turn,S.Stairs,"Drink cock","Open the public drinking cock"))),
        Isle("Bottlebrush Reach",10,"Cullet Garden","Van and Son, glass sweepers",
            "The sweepers sort broken glass for the bottle crops. Van recently retired and Son recently became a parent. Neither is prepared to change the painted name of the business.",
            "A business card folded around a blue glass seed",
            new PostLetter("A blue seed from the sweeping floor",
                "What shall we call the granddaughter of a glass sweeper on the new sign?",
                "For the moment she prefers Captain. Please leave a little space after it."),
            Landfall("wake-cullet-sort","What Is a Blue?",
                "A baby reef rejects every bottle except blue. The shop has enough green fragments to wallpaper a city. Van says blue is in there somewhere.","Sieve Lizard","In the shade the green looks blue. The calf recognizes the sound of its feeding bottle, not its color.",8,
                At(A.Turn,S.West,"Sorting drum","Turn the drum in the shadow of the baskets"),
                At(A.Haul,S.Crane,"Singing shards","Lift the tray that rings like the feeding bottle"),
                At(A.Seat,S.East,"Sample tile","Seat the ringing pieces in a sample tile")),
            Crossing("wake-cullet-note",D.Hunt,"A Bottle in A Flat",
                "A bottle made from the ringing fragments draws an empty milk cart down the strait. Somebody has been using the original bottle as a cart bell.","Follow the ringing milk cart to the calving reef.",
                "Cullet Cuckoo","The milkwoman happily exchanges the bell for a whistle. She was tired of the baby reefs following her all the way home.",8,J.Track,J.Sound,J.DriveOff),
            Crossing("wake-cullet-deliver",D.Convoy,"Three Generations of Freight",
                "Van and Son have soldered an old perambulator to a flat-bottomed boat. The granddaughter travels with the bottle to settle the question of ownership.","Guide the improvised milk boat to the nursery reef.",
                "Nipplejaw","The granddaughter pours the bottle out for the calf. Van says this is a thoroughly satisfactory distribution of the company assets.",8,J.Tow,J.Guide,J.Relay),
            Landfall("wake-cullet-letters","And Company",
                "The family sign is too short for a third name. The girl has already scratched a large C into the wood.","Paintbrush Crab","The sign reads Van and Son and Captain. The Captain immediately promotes the baby calf to Director of Milk.",8,
                At(A.Brace,S.West,"Sign trestle","Brace the old sign over the door"),
                At(A.Haul,S.Crane,"Blue glass letters","Raise the new letters onto the trestle"),
                At(A.Seat,S.East,"Captain’s C","Set the big C where the girl can reach it")))
    ];
}
